/** Exports locally via Android's share sheet or a browser download; never uploads records. */
export async function exportJson(payload: unknown, prefix = 'MoneyFlow_Backup'): Promise<void> {
  const content = JSON.stringify(payload, null, 2)
  const now = new Date()
  const date = `${now.getFullYear()}_${String(now.getMonth() + 1).padStart(2, '0')}_${String(now.getDate()).padStart(2, '0')}`
  const filename = `${prefix}_${date}.json`
  if (Capacitor.isNativePlatform()) {
    const result = await Filesystem.writeFile({ path: filename, data: content, directory: Directory.Cache, encoding: Encoding.UTF8 })
    const previous = localStorage.getItem('moneyflow-last-shared-file')
    localStorage.setItem('moneyflow-last-shared-file', filename)
    if (previous && previous !== filename && /^MoneyFlow_(Backup|Original_Storage)_\d{4}_\d{2}_\d{2}\.json$/.test(previous)) await Filesystem.deleteFile({ path: previous, directory: Directory.Cache }).catch(() => undefined)
    await Share.share({ title: 'MoneyFlow backup', files: [result.uri], dialogTitle: 'Save your private JSON backup' })
    return
  }
  const url = URL.createObjectURL(new Blob([content], { type: 'application/json' }))
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  document.body.append(link)
  link.click()
  link.remove()
  window.setTimeout(() => URL.revokeObjectURL(url), 1000)
}